mapper.select:
select b.person_id,full_name,gender,job_no,person_type,phone,email,status,induction_date,quit_date
from sys_org_person_b b
join sys_org_person_tl tl on tl.person_id = b.person_id and tl.language = #{language}


		status = #{status} and


		person_type in

			#{item}

		and


		(


		FULL_NAME like CONCAT( CONCAT('%',#{fullName} ),'%')


		${montage}


		JOB_NO like CONCAT( CONCAT('%',#{jobNo} ),'%')


		)


order by b.person_id desc

mapper.update:
update sys_org_person_b
gender = #{gender}, job_no = #{jobNo}, person_type = #{personType}, phone = #{phone}, email = #{email}, status = #{status}, induction_date = #{inductionDate}, quit_date = #{quitDate}, LAST_UPDATE_BY = #{lastUpdateBy}, LAST_UPDATE_DATE = #{lastUpdateDate}, LAST_UPDATE_LOGIN = #{lastUpdateLogin}
where person_id = #{personId}

